static int dp[3000];

int cmpBox(const void *a, const void *b) {
  int *x = *(int **)a, *y = *(int **)b;
  return x[0] - y[0];
}

int pileBox(int **box, int boxSize, int *boxColSize) {
  (void)boxColSize;
  qsort(box, boxSize, sizeof(int *), cmpBox);
  int best = 0;
  for (int i = 0; i < boxSize; i++) {
    dp[i] = box[i][2];
    for (int j = 0; j < i; j++) {
      if (box[j][0] < box[i][0] && box[j][1] < box[i][1] && box[j][2] < box[i][2]) {
        if (dp[j] + box[i][2] > dp[i]) dp[i] = dp[j] + box[i][2];
      }
    }
    if (dp[i] > best) best = dp[i];
  }
  return best;
}

class Solution {
public:
  int pileBox(vector<vector<int>> &box) {
    sort(box.begin(), box.end());
    int n = box.size(), best = 0;
    vector<int> dp(n, 0);
    for (int i = 0; i < n; i++) {
      dp[i] = box[i][2];
      for (int j = 0; j < i; j++) {
        if (box[j][0] < box[i][0] && box[j][1] < box[i][1] && box[j][2] < box[i][2]) {
          dp[i] = max(dp[i], dp[j] + box[i][2]);
        }
      }
      best = max(best, dp[i]);
    }
    return best;
  }
};

func pileBox(box [][]int) int {
	sort.Slice(box, func(i, j int) bool {
		if box[i][0] != box[j][0] {
			return box[i][0] < box[j][0]
		}
		return box[i][1] < box[j][1]
	})
	n := len(box)
	dp := make([]int, n)
	best := 0
	for i := 0; i < n; i++ {
		dp[i] = box[i][2]
		for j := 0; j < i; j++ {
			if box[j][0] < box[i][0] && box[j][1] < box[i][1] && box[j][2] < box[i][2] {
				if dp[j]+box[i][2] > dp[i] {
					dp[i] = dp[j] + box[i][2]
				}
			}
		}
		if dp[i] > best {
			best = dp[i]
		}
	}
	return best
}

class Solution {
  public int pileBox(int[][] box) {
    Arrays.sort(box, (a, b) -> a[0] != b[0] ? a[0] - b[0] : (a[1] != b[1] ? a[1] - b[1] : a[2] - b[2]));
    int n = box.length, best = 0;
    int[] dp = new int[n];
    for (int i = 0; i < n; i++) {
      dp[i] = box[i][2];
      for (int j = 0; j < i; j++) {
        if (box[j][0] < box[i][0] && box[j][1] < box[i][1] && box[j][2] < box[i][2]) {
          dp[i] = Math.max(dp[i], dp[j] + box[i][2]);
        }
      }
      best = Math.max(best, dp[i]);
    }
    return best;
  }
}

class Solution:
    def pileBox(self, box: List[List[int]]) -> int:
        box.sort()
        n = len(box)
        dp = [0] * n
        best = 0
        for i in range(n):
            dp[i] = box[i][2]
            for j in range(i):
                if box[j][0] < box[i][0] and box[j][1] < box[i][1] and box[j][2] < box[i][2]:
                    dp[i] = max(dp[i], dp[j] + box[i][2])
            best = max(best, dp[i])
        return best

impl Solution {
  pub fn pile_box(mut box_: Vec<Vec<i32>>) -> i32 {
    box_.sort();
    let n = box_.len();
    let mut dp = vec![0i32; n];
    let mut best = 0;
    for i in 0..n {
      dp[i] = box_[i][2];
      for j in 0..i {
        if box_[j][0] < box_[i][0] && box_[j][1] < box_[i][1] && box_[j][2] < box_[i][2] {
          dp[i] = dp[i].max(dp[j] + box_[i][2]);
        }
      }
      best = best.max(dp[i]);
    }
    best
  }
}

const pileBox = (box: number[][]): number => {
  box.sort((a, b) => a[0] - b[0] || a[1] - b[1] || a[2] - b[2]);
  const n = box.length;
  const dp: number[] = new Array(n).fill(0);
  let best = 0;
  for (let i = 0; i < n; i++) {
    dp[i] = box[i][2];
    for (let j = 0; j < i; j++) {
      if (box[j][0] < box[i][0] && box[j][1] < box[i][1] && box[j][2] < box[i][2]) {
        dp[i] = Math.max(dp[i], dp[j] + box[i][2]);
      }
    }
    best = Math.max(best, dp[i]);
  }
  return best;
};
